import time
from typing import Any, Dict, Optional, Tuple

_MISSING = object()

class TTLCache:
    def __init__(self):
        self._store: Dict[Any, Tuple[Any, float]] = {}

    def get(self, key: Any, default: Any = None) -> Any:
        item = self._store.get(key, _MISSING)
        if item is _MISSING:
            return default
        value, expires_at = item
        if time.monotonic() >= expires_at:
            del self._store[key]
            return default
        return value

    def set(self, key: Any, value: Any, ttl: float) -> None:
        if ttl <= 0:
            self._store.pop(key, None)
            return
        self._store[key] = (value, time.monotonic() + ttl)

    def delete(self, key: Any) -> None:
        self._store.pop(key, None)

    def clear(self) -> None:
        self._store.clear()

    def purge_expired(self) -> int:
        now = time.monotonic()
        expired = [k for k, (_, exp) in self._store.items() if now >= exp]
        for k in expired:
            del self._store[k]
        return len(expired)

    def __len__(self) -> int:
        self.purge_expired()
        return len(self._store)
```

Example:

```python
cache = TTLCache()
cache.set("user:1", {"name": "Ada"}, ttl=5.0)

print(cache.get("user:1"))   # {'name': 'Ada'}
time.sleep(6)
print(cache.get("user:1", "missing"))  # missing
```

Behavior: entries expire lazily on `get`; `purge_expired()`/`__len__` can eagerly remove stale entries. `time.monotonic()` is used so wall-clock changes do not affect TTL.

Complexity: average `O(1)` time for `get`/`set`/`delete`, `O(n)` space for `n` live entries, `O(n)` for `purge_expired()`. This is not thread-safe by default; add a lock if used across threads.
